export function reduce(list, reducer, start) {
  let index = 0;
  let total = start;

  if (start === undefined) {
    if (list.length === 0) {
      throw new TypeError("Reduce of empty array with no initial value");
    }
    total = list[0];
    index = 1;
  }

  for (; index < list.length; index++) {
    total = reducer(total, list[index], index, list);
  }
  return total;
}
